import{_ as s,C as l,c as i,o as d,a3 as o,G as r,j as e,a as n}from"./chunks/framework.Dokpd4od.js";const w=JSON.parse('{"title":"Plan and schedule","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/manufacturing/workflows/plan-and-schedule.md","filePath":"master/supply-chain/manufacturing/workflows/plan-and-schedule.md","lastUpdated":1792041590000}'),h={name:"master/supply-chain/manufacturing/workflows/plan-and-schedule.md"};function c(u,t,p,g,k,f){const a=l("ImagePopup");return d(),i("div",null,[t[0]||(t[0]=o('<h1 id="plan-and-schedule" tabindex="-1">Plan and schedule <a class="header-anchor" href="#plan-and-schedule" aria-label="Permalink to &quot;Plan and schedule&quot;">​</a></h1><p>Planning gives every work order a real time slot. Aureus looks at the working hours of each work center and books the first free slot. It also checks the alternative work centers and picks the one that finishes earliest. Planning is how you see when an order can really finish.</p><blockquote><p><strong>In simple words:</strong> Plan means &quot;put each work order on the calendar of its work center&quot;.</p></blockquote><p>Open the MO at <code>Manufacturing → Operations → Manufacturing Orders</code> and use the <strong>Plan</strong> button.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Plan books work orders, so <strong>Work Orders</strong> must be on in <code>Manufacturing → Settings → Manage Operations</code>. See <a href="./../get-started/manufacturing-settings.html">Manufacturing settings</a>.</p><p>Each work center needs a <strong>Working Hours</strong> calendar. It is a required field on the work center form. See <a href="./../advanced-configuration/work-centers.html">Work centers</a>.</p><h2 id="plan-an-order" tabindex="-1">Plan an order <a class="header-anchor" href="#plan-an-order" aria-label="Permalink to &quot;Plan an order&quot;">​</a></h2><p>Scenario: plan <strong>MO/2</strong>, 2 Business Laptops. It has <strong>Assemble Components</strong> at <strong>Assembly Station</strong> and <strong>Test &amp; Pack</strong> at <strong>Quality &amp; Packing</strong>. Both use <strong>Standard 38 hours/week</strong>.</p><ol><li>Open <strong>MO/2</strong>. It is <strong>Confirmed</strong>.</li><li>Click <strong>Plan</strong>.</li></ol>',10)),r(a,{src:"/images1/manufacturing/plan_button.png",alt:"MO/2 view page with the Plan button highlighted before planning"}),t[1]||(t[1]=e("ol",{start:"3"},[e("li",null,[n("Aureus shows "),e("strong",null,"Manufacturing order planned"),n(".")]),e("li",null,[n("Open the "),e("strong",null,"Work Orders"),n(" tab. Each row now has a "),e("strong",null,"Start"),n(" and an "),e("strong",null,"End"),n(".")])],-1)),r(a,{src:"/images1/manufacturing/plan_work_orders.png",alt:"Work Orders tab of the planned MO with Start and End filled for both rows"}),t[2]||(t[2]=e("ol",{start:"5"},[e("li",null,[n("Check the top of the form. "),e("strong",null,"Scheduled Date"),n(" and "),e("strong",null,"Scheduled End"),n(" show the full span of the plan.")])],-1)),r(a,{src:"/images1/manufacturing/plan_scheduled_end.png",alt:"General section of the planned MO with Scheduled Date and Scheduled End filled"}),t[3]||(t[3]=o(`<p>The order now appears under the <strong>Planned</strong> tab of the list. The header shows <strong>Unplan</strong> in place of <strong>Plan</strong>.</p><h2 id="how-aureus-picks-a-slot" tabindex="-1">How Aureus picks a slot <a class="header-anchor" href="#how-aureus-picks-a-slot" aria-label="Permalink to &quot;How Aureus picks a slot&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Start = later of (Scheduled Date, now)</span></span>
<span class="line"><span>For each work order, in sequence:</span></span>
<span class="line"><span>  try the work center and each alternative work center</span></span>
<span class="line"><span>  find the first free slot inside Working Hours</span></span>
<span class="line"><span>  keep the one that finishes earliest</span></span>
<span class="line"><span>Next work order starts after the previous one ends</span></span></code></pre></div><ul><li>The slot length is the <strong>Expected Duration</strong> of the work order.</li><li>Time outside the <strong>Working Hours</strong> calendar is skipped. A 60 minute task started late Friday can finish on Monday.</li><li>With <strong>Work Order Dependencies</strong> on, a work order waits for the ones in <strong>Blocked By</strong>. See <a href="./../advanced-configuration/work-order-dependencies.html">Work order dependencies</a>.</li></ul><h3 id="alternative-work-centers" tabindex="-1">Alternative work centers <a class="header-anchor" href="#alternative-work-centers" aria-label="Permalink to &quot;Alternative work centers&quot;">​</a></h3><p>Add <strong>Alternative Work Centers</strong> on the work center form. Plan compares them with the main one. If an alternative finishes earlier, the work order moves there. Its <strong>Work Center</strong> and <strong>Expected Duration</strong> update.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Give alternative work centers their own <strong>Working Hours</strong>. Plan then uses whichever team is free first.</p></div><h3 id="expected-duration" tabindex="-1">Expected duration <a class="header-anchor" href="#expected-duration" aria-label="Permalink to &quot;Expected duration&quot;">​</a></h3><p>The length of a slot comes from the work order <strong>Expected Duration</strong>. It starts from the duration set on the operation. See <a href="./../advanced-configuration/operations.html">Operations</a>.</p><h2 id="unplan-an-order" tabindex="-1">Unplan an order <a class="header-anchor" href="#unplan-an-order" aria-label="Permalink to &quot;Unplan an order&quot;">​</a></h2><p>Click <strong>Unplan</strong> to remove the booked slots. The <strong>Start</strong> and <strong>End</strong> of the work orders are cleared. Aureus shows <strong>Manufacturing order un-planned</strong>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>You cannot unplan once work has begun. If a work order is finished, Aureus says &quot;Some work orders are already done, so you cannot un-plan this manufacturing order.&quot; If one is in progress, it says &quot;Some work orders have already started, so you cannot un-plan this manufacturing order.&quot;</p></div><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>There is no defined calendar on work center :name.</td><td>The work center has no <strong>Working Hours</strong>.</td><td>Open the work center, pick <strong>Working Hours</strong>, save.</td></tr><tr><td>Impossible to plan the work order. Please check the work center availabilities.</td><td>No free slot found on the work center or its alternatives.</td><td>Extend the working hours or add an alternative work center.</td></tr></tbody></table><p>The name of the work center replaces <code>:name</code> in the first message.</p><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>Plan creates one booking on the work center calendar for each work order. Unplan deletes those bookings. Plan changes no stock. Components stay reserved from <strong>Confirm</strong>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./manufacturing-orders.html">Manufacturing orders</a></li><li><a href="./work-orders.html">Work orders</a></li><li><a href="./../advanced-configuration/work-centers.html">Work centers</a></li><li><a href="./../advanced-configuration/operations.html">Operations</a></li></ul>`,19))])}const b=s(h,[["render",c]]);export{w as __pageData,b as default};
